import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { useState } from 'react'
import { Text, TextInput, TextInputProps } from 'react-native'
import { KeyboardAvoidingView } from 'react-native-keyboard-controller'

interface InputProps extends TextInputProps {
	label?: string
	error?: string
}

export const Input = ({
	label,
	error,
	style,
	onFocus,
	onBlur,
	...props
}: InputProps) => {
	const { theme } = useTheme()
	const [isFocused, setIsFocused] = useState(false)

	return (
		<KeyboardAvoidingView style={styles.container}>
			{label && <Text style={styles.label(theme)}>{label}</Text>}
			<TextInput
				style={[
					styles.input(theme),
					isFocused && styles.inputActive(theme),
					!!error && styles.invalidInput(theme),
					style
				]}
				placeholderTextColor={colors[theme].gray[400]}
				onFocus={(e) => {
					setIsFocused(true)
					onFocus?.(e)
				}}
				onBlur={(e) => {
					setIsFocused(false)
					onBlur?.(e)
				}}
				{...props}
			/>
			{error && <Text style={styles.errorText(theme)}>{error}</Text>}
		</KeyboardAvoidingView>
	)
}

const styles = defineStyles({
	container: {
		gap: 10
	},
	label: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	input: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[50],
		borderRadius: 18,
		height: 56,
		paddingHorizontal: 20,
		fontSize: 16,
		color: colors[theme].gray[900],
		fontWeight: '500',
		borderWidth: 1,
		borderColor: 'transparent'
	}),
	inputActive: (theme: Theme) => ({
		borderColor: colors[theme].gray[500]
	}),
	invalidInput: (theme: Theme) => ({
		backgroundColor: colors[theme].red[50],
		color: colors[theme].red[600],
		borderColor: colors[theme].red[600]
	}),
	errorText: (theme: Theme) => ({
		color: colors[theme].red[600],
		fontWeight: '500',
		fontSize: 14
	})
})
